package dev.codex.lastzhelper;
import java.io.*;import java.nio.channels.*;import org.json.*;
/** One user-selected map truck. The explicit selected-truck allowance is scoped to this diagnostic only. */
public final class SelectedAttackCheck {
 public static void main(String[] args){try(DeviceInput.Scope inputs=new DeviceInput.Scope()){
  if((args.length!=3&&!(args.length==4&&args[3].equals("--continue-setup")))||!args[2].matches("[0-9]{10,24}"))throw new IOException("Expected live directory, assets and user-selected UUID");File dir=new File(args[0]),assets=new File(args[1]),locks=new File("/data/local/tmp/codex-lastz-helper");locks.mkdirs();
  try(RandomAccessFile f=new RandomAccessFile(new File(locks,"control.lock"),"rw");FileChannel ch=f.getChannel();FileLock lock=ch.tryLock()){
   if(lock==null)throw new IOException("Controller active");StateProbe.pinForeground();StateProbe.snapshot(new File(dir,"probe-cache.txt").getPath());if(!TruckPolicy.MAIN_UID.equals(StateProbe.pinnedUid))throw new IOException("Active Gaarix required");
   File stop=new File(dir,"stop-request");stop.delete();AutomationController c=new AutomationController(dir,new File(assets,"injector"),new File(assets,"input-agent.js"),stop,false,0);c.truckMode="truck-attack";c.mode="selected-attack-check";c.twoFragmentTest=true;c.diagnosticMinimumSlots=1;c.input.foreground();JSONObject truck;
   if(args.length==4){truck=c.attacks.data.getJSONObject("attack:"+args[2]);if(!args[2].equals(truck.getString("id"))||!"one-user-selected-truck-test".equals(truck.optString("diagnostic")))throw new IOException("Selected diagnostic record mismatch");c.requireBattle(truck);c.fightFromSetup(truck);System.out.println(new JSONObject().put("ok",true).put("attacked",c.attacked).put("truckId",args[2]));return;}
   try(GameMemory m=new GameMemory(c.cache)){if(!m.open("UIWorldPoint")||m.state.getInt("modalWindowCount")!=1)throw new IOException("User-selected map preview missing");long data=m.path("UIManagerInstance/windows/UIWorldPoint/View/train_obj/data");String id=Long.toString(GameMemory.number(data,"uuid"));if(!args[2].equals(id))throw new IOException("User-selected truck changed");int[] base=TruckProbe.fragmentSlots(data,"baseGoods"),extra=TruckProbe.fragmentSlots(data,"extraGoods");truck=new JSONObject().put("id",id).put("owner",GameMemory.string(data,"name")).put("serverId",GameMemory.number(data,"serverId")).put("quality",GameMemory.number(data,"quality")).put("power",GameMemory.number(data,"power")).put("orangeFragmentSlots",base[0]+extra[0]).put("orangeFragmentQuantity",base[1]+extra[1]).put("diagnostic","one-user-selected-truck-test");}
   if(!c.classify(truck).equals("ALERT_TARGET"))throw new IOException("Selected truck fails the user-selected test rules or power cap");String key="attack:"+args[2];if(c.attacks.contains(key))throw new IOException("Attack already recorded; no retry");c.verifyMapTruck(truck,"ALERT_TARGET");c.attacks.pending(key,new JSONObject(truck.toString()).put("kind","truck-attack"));System.out.println(new JSONObject().put("event","selected-truck").put("truck",truck));System.out.flush();c.attackFromMap(truck);System.out.println(new JSONObject().put("ok",true).put("attacked",c.attacked).put("shared",c.sent).put("truckId",args[2]));
  }
 }catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
